import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"ApiController","description":"","frontmatter":{"sidebarPos":3,"sidebarTitle":"ApiController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/api-controller.md","filePath":"system-reference/backend/http/controllers/api-controller.md","lastUpdated":1778363927000}'),d={name:"system-reference/backend/http/controllers/api-controller.md"},s=a('<h1 id="apicontroller" tabindex="-1">ApiController <a class="header-anchor" href="#apicontroller" aria-label="Permalink to &quot;ApiController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/ApiController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>CoreController</code><br><strong>Traits</strong>: <code>ApiResponses</code>, <code>ApiVersioning</code>, <code>ApiAuthentication</code>, <code>ApiRateLimiting</code>, <code>ApiValidation</code>, <code>ApiPagination</code>, <code>ApiFiltering</code>, <code>ApiSorting</code>, <code>ApiRelationships</code></p><p>Abstract base controller for RESTful JSON APIs. Provides versioning, rate limiting, relationship loading, bulk operations, and a standardised response envelope on top of <code>CoreController</code>.</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __construct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $app, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $request)</span></span></code></pre></div><p>Calls <code>CoreController::__construct()</code> then runs:</p><ol><li><code>setApiVersion()</code> — resolves version from request header or default.</li><li><code>setApiResourceClasses()</code> — finds the API resource and collection classes.</li><li><code>setApiDefaults()</code> — loads per-route API config (per-page limits, includes, etc.).</li></ol><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>$apiVersion</code></td><td><code>string</code></td><td><code>&#39;v1&#39;</code></td><td>Active API version</td></tr><tr><td><code>$defaultPerPage</code></td><td><code>int</code></td><td><code>15</code></td><td>Default items per page</td></tr><tr><td><code>$maxPerPage</code></td><td><code>int</code></td><td><code>100</code></td><td>Maximum allowed items per page</td></tr><tr><td><code>$defaultIncludes</code></td><td><code>array</code></td><td><code>[]</code></td><td>Relationships always loaded</td></tr><tr><td><code>$availableIncludes</code></td><td><code>array</code></td><td><code>[]</code></td><td>Relationships the client may request</td></tr><tr><td><code>$apiResourceClass</code></td><td><code>string</code></td><td>—</td><td><code>JsonResource</code> class for single items</td></tr><tr><td><code>$apiResourceCollectionClass</code></td><td><code>string</code></td><td>—</td><td><code>ResourceCollection</code> class</td></tr><tr><td><code>$wrapResponses</code></td><td><code>bool</code></td><td><code>true</code></td><td>Wrap data in a <code>data</code> envelope</td></tr><tr><td><code>$responseMetadata</code></td><td><code>array</code></td><td><code>[]</code></td><td>Extra fields merged into every response</td></tr></tbody></table><h2 id="standard-crud-endpoints" tabindex="-1">Standard CRUD Endpoints <a class="header-anchor" href="#standard-crud-endpoints" aria-label="Permalink to &quot;Standard CRUD Endpoints&quot;">​</a></h2><table><thead><tr><th>Method</th><th>HTTP</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>index()</code></td><td>GET</td><td><code>/api/{resource}</code></td><td>Paginated list with filtering and sorting</td></tr><tr><td><code>show(int $id)</code></td><td>GET</td><td><code>/api/{resource}/{id}</code></td><td>Single item with includes</td></tr><tr><td><code>store()</code></td><td>POST</td><td><code>/api/{resource}</code></td><td>Create — returns 201</td></tr><tr><td><code>update(int $id)</code></td><td>PUT</td><td><code>/api/{resource}/{id}</code></td><td>Update — returns 200</td></tr><tr><td><code>destroy(int $id)</code></td><td>DELETE</td><td><code>/api/{resource}/{id}</code></td><td>Soft-delete — returns 200</td></tr></tbody></table><h2 id="extended-endpoints" tabindex="-1">Extended Endpoints <a class="header-anchor" href="#extended-endpoints" aria-label="Permalink to &quot;Extended Endpoints&quot;">​</a></h2><h3 id="bulk-jsonresponse" tabindex="-1"><code>bulk(): JsonResponse</code> <a class="header-anchor" href="#bulk-jsonresponse" aria-label="Permalink to &quot;`bulk(): JsonResponse`&quot;">​</a></h3><p>Fetches multiple items by an array of IDs. Accepts <code>ids[]</code> in the request body.</p><h3 id="search-jsonresponse" tabindex="-1"><code>search(): JsonResponse</code> <a class="header-anchor" href="#search-jsonresponse" aria-label="Permalink to &quot;`search(): JsonResponse`&quot;">​</a></h3><p>Full-text search across the module&#39;s searchable columns. Returns a paginated collection.</p><h3 id="filters-jsonresponse" tabindex="-1"><code>filters(): JsonResponse</code> <a class="header-anchor" href="#filters-jsonresponse" aria-label="Permalink to &quot;`filters(): JsonResponse`&quot;">​</a></h3><p>Returns all available filters, sort fields, and includable relationships for the client to use in subsequent requests.</p><h3 id="meta-jsonresponse" tabindex="-1"><code>meta(): JsonResponse</code> <a class="header-anchor" href="#meta-jsonresponse" aria-label="Permalink to &quot;`meta(): JsonResponse`&quot;">​</a></h3><p>Returns metadata about the resource — relationship counts, available scopes, and config flags.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><h3 id="getperpage-int" tabindex="-1"><code>getPerPage(): int</code> <a class="header-anchor" href="#getperpage-int" aria-label="Permalink to &quot;`getPerPage(): int`&quot;">​</a></h3><p>Returns <code>per_page</code> from the request, clamped between <code>1</code> and <code>$maxPerPage</code>.</p><h2 id="relationships-includes" tabindex="-1">Relationships / Includes <a class="header-anchor" href="#relationships-includes" aria-label="Permalink to &quot;Relationships / Includes&quot;">​</a></h2><h3 id="getincludes-array" tabindex="-1"><code>getIncludes(): array</code> <a class="header-anchor" href="#getincludes-array" aria-label="Permalink to &quot;`getIncludes(): array`&quot;">​</a></h3><p>Parses the <code>include</code> query parameter (comma-separated) and validates each name against <code>$availableIncludes</code>.</p><h3 id="getincludesforeagerloading-array" tabindex="-1"><code>getIncludesForEagerLoading(): array</code> <a class="header-anchor" href="#getincludesforeagerloading-array" aria-label="Permalink to &quot;`getIncludesForEagerLoading(): array`&quot;">​</a></h3><p>Returns includes formatted for <code>with()</code> — may attach constraints (e.g. ordering) to specific relationships.</p><h2 id="response-helpers" tabindex="-1">Response Helpers <a class="header-anchor" href="#response-helpers" aria-label="Permalink to &quot;Response Helpers&quot;">​</a></h2><h3 id="respondwithresource-resource-int-status-200-jsonresponse" tabindex="-1"><code>respondWithResource($resource, int $status = 200): JsonResponse</code> <a class="header-anchor" href="#respondwithresource-resource-int-status-200-jsonresponse" aria-label="Permalink to &quot;`respondWithResource($resource, int $status = 200): JsonResponse`&quot;">​</a></h3><p>Wraps a single <code>JsonResource</code> instance in the configured envelope and returns it.</p><h3 id="respondwithcollection-collection-int-status-200-jsonresponse" tabindex="-1"><code>respondWithCollection($collection, int $status = 200): JsonResponse</code> <a class="header-anchor" href="#respondwithcollection-collection-int-status-200-jsonresponse" aria-label="Permalink to &quot;`respondWithCollection($collection, int $status = 200): JsonResponse`&quot;">​</a></h3><p>Wraps a <code>ResourceCollection</code> with pagination meta.</p><h3 id="respondwithdata-data-int-status-200-jsonresponse" tabindex="-1"><code>respondWithData($data, int $status = 200): JsonResponse</code> <a class="header-anchor" href="#respondwithdata-data-int-status-200-jsonresponse" aria-label="Permalink to &quot;`respondWithData($data, int $status = 200): JsonResponse`&quot;">​</a></h3><p>Returns arbitrary data. When <code>$wrapResponses</code> is <code>true</code>, nests under a <code>data</code> key.</p><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><p>Rate limit headers (<code>X-RateLimit-Limit</code>, <code>X-RateLimit-Remaining</code>) are added to every response via the <code>ApiRateLimiting</code> trait. Limits are configured per route in the module config.</p><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>The API version is read from the <code>Accept</code> header (e.g. <code>Accept: application/vnd.api+json;version=v2</code>) or falls back to <code>$apiVersion</code>. The resolved version is available throughout the request lifecycle.</p>',39),r=[s];function i(n,c,l,p,h,u){return o(),t("div",null,r)}const m=e(d,[["render",i]]);export{b as __pageData,m as default};
